"""post.py <clip_dir>: skeleton overlay frames, pixel-art style frames, frame-aligned H.264 streams, per-clip checks, final json.
Prints POST_OK / POST_FAIL <reasons>.  Output: <clip_dir>/<clip_id>_{render,white_box,skeleton,box,class}.mp4, plus one
<clip_id>_render_<style>.mp4 per extra render style (toon, realistic, pixel), <clip_id>.json"""
import json, os, subprocess, sys
import numpy as np
from PIL import Image, ImageDraw
d = sys.argv[1]
# a clip generated by the previous gen_clip.py (no box/class passes) is still posted, with its three streams
m = json.load(open(f"{d}/meta.json"))
W, H, NF, FPS, cid = m["width"], m["height"], m["frames"], m["fps"], m["clip_id"]
STYLES = m.get("styles", {})
# ---- pixel-art style: area-downsample the toon frames (or the base render), quantise to one palette per clip, nearest upscale
if "render_pixel" in STYLES:
    src = "render_toon" if "render_toon" in STYLES and os.path.isdir(f"{d}/render_toon") else "render"
    fac = (4, 6)[m["seed"] % 2]; ncol = (16, 24, 32)[(m["seed"] // 2) % 3]
    sw, sh = W // fac, H // fac
    small = lambda f: Image.open(f"{d}/{src}/{f:04d}.png").convert("RGB").resize((sw, sh), Image.BOX)
    pf = sorted(set(np.linspace(1, NF, 8).astype(int)))
    strip = Image.new("RGB", (sw, sh * len(pf)))
    for k, f in enumerate(pf): strip.paste(small(f), (0, k * sh))
    pal = strip.quantize(colors=ncol, method=Image.Quantize.MEDIANCUT)
    os.makedirs(f"{d}/render_pixel", exist_ok=True)
    for f in range(1, NF + 1):
        small(f).quantize(palette=pal, dither=Image.Dither.NONE).convert("RGB").resize((sw * fac, sh * fac), Image.NEAREST) \
            .save(f"{d}/render_pixel/{f:04d}.png", compress_level=1)
    m["pixel_art"] = dict(source=src, pixel_size=fac, grid=[sw, sh], palette_colors=ncol)
EXTRA = tuple(s for s in ("render_toon", "render_realistic", "render_pixel") if s in STYLES and os.path.isdir(f"{d}/{s}"))
m["styles"] = {k: v for k, v in STYLES.items() if k == "render" or k in EXTRA}
def col(n):
    n = n.lower()
    if n.endswith(".l") or ".l_" in n or "left" in n: return (255, 80, 80)
    if n.endswith(".r") or ".r_" in n or "right" in n: return (80, 160, 255)
    return (255, 220, 60)
STREAMS = ("render", "white_box", "skeleton") + (("box", "class") if os.path.isdir(f"{d}/box") else ()) + EXTRA
os.makedirs(f"{d}/skeleton", exist_ok=True)
for f in range(1, NF + 1):
    im = Image.new("RGB", (W, H)); dr = ImageDraw.Draw(im)
    for ch in m["characters"]:
        fd = ch["frames"][f - 1]
        if not fd["visible"]: continue
        J = fd["j2d"]; names = ch["joint_names"]
        for a, b in ch["edges"]:
            if J[a][2] > 0 and J[b][2] > 0:
                dr.line([tuple(J[a][:2]), tuple(J[b][:2])], fill=col(names[b]), width=6)
        for j in J:
            if j[2] > 0: dr.ellipse([j[0] - 3, j[1] - 3, j[0] + 3, j[1] + 3], fill=(255, 255, 255))
    im.save(f"{d}/skeleton/{f:04d}.png", compress_level=1)
# ---- checks on decoded PNGs (sampled)
reasons = []
samp = sorted(set(np.linspace(1, NF, 12).astype(int)))
lum, std = [], []
for f in samp:
    a = np.asarray(Image.open(f"{d}/render/{f:04d}.png").convert("L"), dtype=np.float32)
    lum.append(float(a.mean())); std.append(float(a.std()))
if min(lum) < 8: reasons.append(f"render_dark(min_mean={min(lum):.1f})")
if min(std) < 6: reasons.append(f"render_uniform(min_std={min(std):.1f})")
wb_fill = []
for f in samp:
    a = np.asarray(Image.open(f"{d}/white_box/{f:04d}.png").convert("L"), dtype=np.int16)
    bgv = 80  # Workbench world colour 0.08 (linear) -> sRGB 80; geometry is lit grey and varies
    wb_fill.append(float(((np.abs(a - bgv) > 3)).mean()) if a.std() > 3 else 0.0)
if min(wb_fill) < 0.05: reasons.append(f"white_box_empty(min_fill={min(wb_fill):.3f})")
bx_fill, cl_fill = [], []
for f in (samp if "box" in STREAMS else []):  # box pass: same background as the white box; class pass: background black
    a = np.asarray(Image.open(f"{d}/box/{f:04d}.png").convert("L"), dtype=np.int16)
    bx_fill.append(float(((np.abs(a - 80) > 3)).mean()) if a.std() > 3 else 0.0)
    c = np.asarray(Image.open(f"{d}/class/{f:04d}.png").convert("RGB"))
    cl_fill.append(float((c.max(2) > 0).mean()))
if bx_fill and min(bx_fill) < 0.05: reasons.append(f"box_empty(min_fill={min(bx_fill):.3f})")
if cl_fill and min(cl_fill) < 0.05: reasons.append(f"class_empty(min_fill={min(cl_fill):.3f})")
vis = m["checks"]["player_visible_frac"]
if vis < 0.5: reasons.append(f"character_visible({vis:.2f})")
cnt = [len(os.listdir(f"{d}/{s}")) for s in STREAMS]
if len(set(cnt)) != 1 or cnt[0] < NF: reasons.append(f"frame_count{cnt}")
m["checks"].update(render_mean_luma_min=round(min(lum), 2), render_std_min=round(min(std), 2),
                   white_box_fill_min=round(min(wb_fill), 4), box_fill_min=round(min(bx_fill), 4) if bx_fill else None, class_fill_min=round(min(cl_fill), 4) if cl_fill else None, passed=not reasons, fail_reasons=reasons)
# ---- encode (only if passed)
if not reasons:
    for s in STREAMS:
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-framerate", str(FPS), "-start_number", "1", "-i", f"{d}/{s}/%04d.png",
                        "-frames:v", str(NF), "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "17", "-preset", "medium",
                        "-threads", "4", "-movflags", "+faststart", f"{d}/{cid}_{s}.mp4"], check=True)
    m["files"] = {s: f"{cid}_{s}.mp4" for s in STREAMS}
json.dump(m, open(f"{d}/{cid}.json", "w"), separators=(",", ":"))
print("POST_OK" if not reasons else "POST_FAIL " + " ".join(reasons), flush=True)
